class Solution {
public:
    int countQuadruples(string firstString, string secondString) {
        int best=INT_MAX, ways=0;
        int first[26], last[26];
        fill(first,first+26,-1);
        fill(last,last+26,-1);
        for (int i=0;i<(int)firstString.size();++i)
            if (first[firstString[i]-'a']==-1) first[firstString[i]-'a']=i;
        for (int i=0;i<(int)secondString.size();++i)
            last[secondString[i]-'a']=i;
        for (int c=0;c<26;++c) {
            if (first[c]==-1 || last[c]==-1) continue;
            int diff=first[c]-last[c];
            if (diff<best) {best=diff; ways=1;}
            else if (diff==best) ++ways;
        }
        return ways;
    }
};
